def offset_views(iterable, offsets=(-1, 0, 1), longest=False, fillvalue=None):
    """Yield tuples whose elements are offset from *iterable*

>>> list(offset_views([0, 1, 2, 3]))
[(None, 0, 1), (0, 1, 2), (1, 2, 3)]
>>> list(offset_views(range(8), offsets=(0, 2, 4)))
[(0, 2, 4), (1, 3, 5), (2, 4, 6), (3, 5, 7)]"""
    from itertools import zip_longest, islice, tee

    offsets = tuple(offsets)
    iterables = []
    iterators = tee(iterable, len(offsets))

    for it, offset in zip(iterators, offsets):
        if offset < 0:
            iterables.append(islice(it, abs(offset), None))
        elif offset > 0:
            next(islice(it, offset, offset), None)
            iterables.append(it)
        else:
            iterables.append(it)

    if longest:
        yield from zip_longest(*iterables, fillvalue=fillvalue)
    else:
        yield from zip(*iterables)

